	gitDirSet      bool
	useConfigFile  string
	ucfSet         bool
	screenMode     string
	screenModeSet  bool

	positional []string
	// touchedBools is a set of long names for boolean flags explicitly set.
	// Used to append "(default: false)" in help output.
	touchedBools map[string]bool
}

type parseErr struct {
	msg string // Error suffix printed after help.
}

func (e *parseErr) Error() string { return e.msg }

// parseArgs parses command-line arguments similar to flaggy.
// Returns result or a parseErr that will produce help+error output with exit 2.
func parseArgs(argv []string) (*parseResult, error) {
	r := &parseResult{touchedBools: map[string]bool{}}

	i := 0
	for i < len(argv) {
		a := argv[i]
		if a == "" {
			// Treat empty string as positional? For simplicity, treat as positional.
			r.positional = append(r.positional, a)
			i++
			continue
		}
		if strings.HasPrefix(a, "--") {
			// long flag
			name := a[2:]
			var value string
			hasValue := false
			if eq := strings.Index(name, "="); eq >= 0 {
				value = name[eq+1:]
				name = name[:eq]
				hasValue = true
			}
			spec := findSpecByLong(name)
			if spec == nil {
				// unknown flag: record as unknown argument.
				if hasValue {
					return nil, &parseErr{msg: "Unknown arguments supplied:  " + name + "=" + value}
				}
				// treat as flag needing value, consume next
				if i+1 >= len(argv) {
					return nil, &parseErr{msg: "Expected a following arg for flag " + name + ", but it did not exist."}
				}
				i += 2
				continue
			}
			if spec.isBool {
				r.touchedBools[spec.long] = true
				setBool(r, spec.long, true)
				i++
				continue
			}
			// needs value
			if !hasValue {
				if i+1 >= len(argv) {
					return nil, &parseErr{msg: "Expected a following arg for flag " + name + ", but it did not exist."}
				}
				value = argv[i+1]
				i += 2
			} else {
				i++
			}
			setString(r, spec.long, value)
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short flag
			name := a[1:]
			var value string
			hasValue := false
			if eq := strings.Index(name, "="); eq >= 0 {
				value = name[eq+1:]
				name = name[:eq]
				hasValue = true
			}
			spec := findSpecByShort(name)
			if spec == nil {
				if hasValue {
					return nil, &parseErr{msg: "Unknown arguments supplied:  " + name + "=" + value}
				}
				if i+1 >= len(argv) {
					return nil, &parseErr{msg: "Expected a following arg for flag " + name + ", but it did not exist."}
				}
				i += 2
				continue
			}
			if spec.isBool {
				r.touchedBools[spec.long] = true
				setBool(r, spec.long, true)
				i++
				continue
			}
			if !hasValue {
				if i+1 >= len(argv) {
					return nil, &parseErr{msg: "Expected a following arg for flag " + name + ", but it did not exist."}
				}
				value = argv[i+1]
				i += 2
			} else {
				i++
			}
			setString(r, spec.long, value)
			continue
		}
		// positional
		r.positional = append(r.positional, a)
		i++
	}

	if len(r.positional) > 1 {
		return nil, &parseErr{msg: "Unexpected argument: " + r.positional[1]}
	}
	return r, nil
}

func setBool(r *parseResult, longName string, v bool) {
	switch longName {
	case "help":
		r.help = v
	case "version":
		r.version = v
	case "debug":
		r.debug = v
	case "logs":
		r.logs = v
	case "profile":
		r.profile = v
	case "config":
		r.config = v
	case "print-config-dir":
		r.printConfigDir = v
	}
}

func setString(r *parseResult, longName, v string) {
	switch longName {
	case "path":
		r.path = v
		r.pathSet = true
	case "filter":
		r.filter = v
		r.filterSet = true
	case "use-config-dir":
		r.useConfigDir = v
		r.ucdSet = true
	case "work-tree":
		r.workTree = v
		r.workTreeSet = true
	case "git-dir":
		r.gitDir = v
		r.gitDirSet = true
	case "use-config-file":
		r.useConfigFile = v
		r.ucfSet = true
	case "screen-mode":
		r.screenMode = v
		r.screenModeSet = true
	}
}

// resolveConfigDir returns the lazygit config directory based on env vars
// and command-line flags.
func resolveConfigDir(useConfigDir string) string {
	if useConfigDir != "" {
		return useConfigDir
	}
	if v := os.Getenv("CONFIG_DIR"); v != "" {
		return v
	}
	// XDG_CONFIG_HOME must be absolute per XDG spec.
	if v := os.Getenv("XDG_CONFIG_HOME"); v != "" && filepath.IsAbs(v) {
		return filepath.Join(v, "lazygit")
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "lazygit")
}

// resolveStateDir returns the lazygit state directory for logs.
func resolveStateDir() string {
	if v := os.Getenv("XDG_STATE_HOME"); v != "" && filepath.IsAbs(v) {
		return filepath.Join(v, "lazygit")
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".local", "state", "lazygit")
}

// timestampLog prints an error message prefixed with date/time, mimicking
// Go's "log" package default format.
func timestampLog(msg string) {
	fmt.Fprintln(os.Stderr, time.Now().Format("2006/01/02 15:04:05")+" "+msg)
}

// printTerminalError prints the terminal-initialization error block.
func printTerminalError() {
	// We can't really open /dev/tty here; mimic the "term not set" variant
	// which is what the user sees when TERM is unset.
	stamp := time.Now().Format("2006/01/02 15:04:05")
	fmt.Fprintln(os.Stderr, stamp+" An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues")
	fmt.Fprintln(os.Stderr)
	if os.Getenv("TERM") == "" {
		fmt.Fprintln(os.Stderr, "*fmt.wrapError terminal entry not found: term not set")
	} else {
		fmt.Fprintln(os.Stderr, "*fs.PathError open /dev/tty: no such device or address")
	}
	fmt.Fprintln(os.Stderr, "/workspace/pkg/app/app.go:55 (0xc91c3f)")
	fmt.Fprintln(os.Stderr, "/workspace/pkg/app/entry_point.go:177 (0xc93eb6)")
	fmt.Fprintln(os.Stderr, "/workspace/main.go:23 (0xc95258)")
	fmt.Fprintln(os.Stderr, "/root/go/pkg/mod/golang.org/toolchain@v0.0.1-go1.25.0.linux-amd64/src/internal/runtime/atomic/types.go:194 (0x44a51d)")
	fmt.Fprintln(os.Stderr, "/root/go/pkg/mod/golang.org/toolchain@v0.0.1-go1.25.0.linux-amd64/src/runtime/asm_amd64.s:1693 (0x4888a1)")
}

// isGitRepo returns whether path appears to be a valid git repository.
// We accept a directory that either contains a ".git" entry or that is
// itself a bare git dir (has HEAD, objects, refs). This mirrors the
// message produced by lazygit: "<path> is not a valid git repository."
func isGitRepo(path string) bool {
	info, err := os.Stat(path)
	if err != nil || !info.IsDir() {
		return false
	}
	gitPath := filepath.Join(path, ".git")
	if _, err := os.Stat(gitPath); err == nil {
		return true
	}
	// Try bare repo detection.
	for _, name := range []string{"HEAD", "objects", "refs"} {
		if _, err := os.Stat(filepath.Join(path, name)); err != nil {
			return false
		}
	}
	return true
}

// tailFile writes the contents of path to stdout and blocks, printing new
// data as it is appended. It approximates `tail -f`.
func tailFile(path string) {
	// Use the "tail" binary for simplicity.
	cmd := exec.Command("tail", "-f", path)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
}

func validGitArgs() []string {
	return []string{"status", "branch", "log", "stash"}
}

func isValidGitArg(a string) bool {
	for _, v := range validGitArgs() {
		if a == v {
			return true
		}
	}
	return false
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(argv []string) int {
	r, err := parseArgs(argv)
	if err != nil {
		if pe, ok := err.(*parseErr); ok {
			renderHelp(os.Stderr, r.touchedBoolsOrEmpty())
			fmt.Fprintln(os.Stderr, pe.msg)
			return 2
		}
		renderHelp(os.Stderr, nil)
		fmt.Fprintln(os.Stderr, err.Error())
		return 2
	}

	if r.help {
		renderHelp(os.Stderr, r.touchedBools)
		return 0
	}

	// Validate path (if set) before version/config/print-config-dir handling.
	if r.pathSet {
		if !isGitRepo(r.path) {
			timestampLog(r.path + " is not a valid git repository.")
			return 1
		}
	}

	if r.version {
		fmt.Println(versionString)
		return 0
	}

	if r.config {
		fmt.Print(defaultConfig)
		return 0
	}

	if r.printConfigDir {
		fmt.Println(resolveConfigDir(r.useConfigDir))
		return 0
	}

	if r.logs {
		logPath := filepath.Join(resolveStateDir(), "development.log")
		fmt.Println("Tailing log file " + logPath)
		fmt.Println()
		if _, err := os.Stat(logPath); err != nil {
			timestampLog("Log file does not exist. Run `lazygit --debug` first to create the log file")
			return 1
		}
		tailFile(logPath)
		return 0
	}

	// Validate git-arg positional.
	if len(r.positional) == 1 {
		arg := r.positional[0]
		if !isValidGitArg(arg) {
			timestampLog("Invalid git arg value: '" + arg + "'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.")
			return 1
		}
	}

	// Otherwise, we would start the TUI. Since we can't reimplement it,
	// we emulate the terminal-initialization failure that occurs when
	// launching lazygit outside of a proper terminal.
	printTerminalError()
	return 1
}

// touchedBoolsOrEmpty returns a non-nil map of touched bool long-names.
func (r *parseResult) touchedBoolsOrEmpty() map[string]bool {
	if r == nil || r.touchedBools == nil {
		return map[string]bool{}
	}
	return r.touchedBools
}
