// We accept a directory that either contains a ".git" entry or that is
// itself a bare git dir (has HEAD, objects, refs). This mirrors the
// message produced by lazygit: "<path> is not a valid git repository."
func isGitRepo(path string) bool {
	info, err := os.Stat(path)
	if err != nil || !info.IsDir() {
		return false
	}
	gitPath := filepath.Join(path, ".git")
	if _, err := os.Stat(gitPath); err == nil {
		return true
	}
