func run(argv []string) int {
	r, err := parseArgs(argv)
	if err != nil {
		if pe, ok := err.(*parseErr); ok {
			renderHelp(os.Stderr, r.touchedBoolsOrEmpty())
			fmt.Fprintln(os.Stderr, pe.msg)
			return 2
		}
		renderHelp(os.Stderr, nil)
		fmt.Fprintln(os.Stderr, err.Error())
		return 2
	}

	if r.help {
		renderHelp(os.Stderr, r.touchedBools)
		return 0
	}

	// Validate path (if set) before version/config/print-config-dir handling.
	if r.pathSet {
		if !isGitRepo(r.path) {
			timestampLog(r.path + " is not a valid git repository.")
			return 1
		}
	}

	if r.version {
		fmt.Println(versionString)
		return 0
	}

	if r.config {
		fmt.Print(defaultConfig)
		return 0
	}

	if r.printConfigDir {
		fmt.Println(resolveConfigDir(r.useConfigDir))
		return 0
	}

	if r.logs {
		logPath := filepath.Join(resolveStateDir(), "development.log")
		fmt.Println("Tailing log file " + logPath)
		fmt.Println()
		if _, err := os.Stat(logPath); err != nil {
			timestampLog("Log file does not exist. Run `lazygit --debug` first to create the log file")
			return 1
		}
		tailFile(logPath)
		return 0
	}

