	if len(r.positional) == 1 {
		arg := r.positional[0]
		if !isValidGitArg(arg) {
			timestampLog("Invalid git arg value: '" + arg + "'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.")
